def f(x):
    x += 1
    while x % 10 == 0:
        x //= 10
    return x

def solve(n):
    visited = set()
    stack = [n]

    while stack:
        current = stack.pop()
        if current in visited:
            continue
        visited.add(current)

        next_val = f(current)
        if next_val not in visited:
            stack.append(next_val)

    return len(visited)

n = int(input())
print(solve(n))
