def is_magic_number(n):
    s = str(n)
    # We can only use digits 1, 4, and 14, 144
    # So we need to check if we can break the string into parts that are either "1", "14", or "144"

    # Use dynamic programming approach
    dp = [False] * (len(s) + 1)
    dp[0] = True  # Empty string is valid

    for i in range(1, len(s) + 1):
        # Check if we can form a valid number ending at position i
        # Try all possible valid substrings ending at i
        if i >= 1:
            # Check if "1" can be used
            if s[i-1] == '1':
                dp[i] = dp[i] or dp[i-1]

        if i >= 2:
            # Check if "14" can be used
            if s[i-2:i] == "14":
                dp[i] = dp[i] or dp[i-2]

        if i >= 3:
            # Check if "144" can be used
            if s[i-3:i] == "144":
                dp[i] = dp[i] or dp[i-3]

    return dp[len(s)]

# Read input
n = int(input().strip())
if is_magic_number(n):
    print("YES")
else:
    print("NO")
