def solve():
    lines = []
    for _ in range(3):
        line = input().strip()
        lines.append(line)

    # Parse the three comparisons
    comparisons = []
    for line in lines:
        if '<' in line:
            left, right = line.split('<')
            comparisons.append((left, right, 'less'))
        else:  # '>' in line
            left, right = line.split('>')
            comparisons.append((left, right, 'greater'))

    # Create a dictionary to store the relative weights
    # We'll use a graph where each node is a coin and edges represent inequalities
    graph = {}
    for coin in ['A', 'B', 'C']:
        graph[coin] = []

    # Add edges based on comparisons
    for left, right, relation in comparisons:
        if relation == 'less':
            graph[left].append(right)  # left < right
            graph[right].append(left)  # right > left
        else:  # greater
            graph[left].append(right)  # left > right
            graph[right].append(left)  # right < left

    # Try to assign weights to each coin
    # We'll use topological sorting to find a consistent ordering
    # First, build a directed graph from the comparisons
    directed_graph = {}
    for coin in ['A', 'B', 'C']:
        directed_graph[coin] = []

    for left, right, relation in comparisons:
        if relation == 'less':
            directed_graph[left].append(right)  # left < right
        else:  # greater
            directed_graph[right].append(left)  # right < left

    # Check for cycles (which would mean contradiction)
    visited = {}
    in_stack = {}

    def has_cycle(node):
        if node in in_stack:
            return True
        if node in visited:
            return False

        visited[node] = True
        in_stack[node] = True

        for neighbor in directed_graph[node]:
            if has_cycle(neighbor):
                return True

        in_stack[node] = False
        return False

    # Check if there's a cycle in the directed graph
    for coin in ['A', 'B', 'C']:
        if has_cycle(coin):
            print("Impossible")
            return

    # If no cycle, we can find a topological ordering
    # We'll use Kahn's algorithm to get the ordering
    indegree = {coin: 0 for coin in ['A', 'B', 'C']}
    for coin in ['A', 'B', 'C']:
        for neighbor in directed_graph[coin]:
            indegree[neighbor] += 1

    # Get nodes with indegree 0
    queue = []
    for coin in ['A', 'B', 'C']:
        if indegree[coin] == 0:
            queue.append(coin)

    # Topological sort
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)

        for neighbor in directed_graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # If we have exactly 3 nodes in result, we have a valid ordering
    if len(result) == 3:
        # The result is in increasing order (lightest to heaviest)
        print(''.join(result))
    else:
        print("Impossible")

